"""Run-of-show planning: a non-overlapping programme from evidenced times plus Programme planner decisions.

Source facts: the event window, keynote time, setup and teardown windows, the demo roster and the
10 + 3 minute demo durations (Phase 3 baseline). Planner decisions: opening, lunch, break and closing
durations, ordering and grouping (`references/programme-decisions.json`, owned by Programme, pending
review). The brief delegates these choices to the planner (N-BRIEF-planner_schedule_choices).
Gaps are shown as unallocated Programme buffer; no activity is invented to fill them.

This is a planning layer: it does time arithmetic. It reads the Phase 3 decision model as data and
never changes it.
"""

from __future__ import annotations

import json
import math
from datetime import datetime, timedelta
from pathlib import Path

from .config import REFERENCES_DIR

REQUIRED_BASELINE = ("B-event-window", "B-keynote", "B-programme", "B-readiness", "B-teardown")
SOURCE, PLANNER, MIXED, UNALLOCATED = "source", "planner-decision", "source-duration, planner-placement", "unallocated"


def load_decisions(path: Path | None = None) -> dict:
    return json.loads((path or REFERENCES_DIR / "programme-decisions.json").read_text(encoding="utf-8"))


def plan(decision: dict, claims: list[dict], decisions_file: Path | None = None) -> dict:
    base = {b["id"]: b for b in decision["baseline"]}
    claim = {c["id"]: c for c in claims}
    ref = load_decisions(decisions_file)
    pd = {d["id"]: d for d in ref["decisions"]}
    delegation = claim.get("N-BRIEF-planner_schedule_choices")
    decision_records = [{
        "id": d["id"], "summary": d["summary"], "value": d["value"], "kind": "planner-decision",
        "owner": ref["owner"], "status": ref["status"],
        "evidence_ids": ["N-BRIEF-planner_schedule_choices", "N-BRIEF-roster_change_owner"],
        "rationale": "The sources do not supply this value; the brief leaves it to the planner."}
        for d in ref["decisions"]]

    missing = [b for b in REQUIRED_BASELINE if base.get(b, {}).get("support") != "supported"]
    if delegation is None or delegation.get("support") != "supported":
        missing.append("N-BRIEF-planner_schedule_choices")
    if missing:
        return _unresolved(f"inputs not supported: {missing}", missing, decision_records)

    win, key, prog = base["B-event-window"]["value"], base["B-keynote"]["value"], base["B-programme"]["value"]
    ready, tear = base["B-readiness"]["value"], base["B-teardown"]["value"]
    start, end = datetime.fromisoformat(win["start"]), datetime.fromisoformat(win["end"])
    k_start, k_end = datetime.fromisoformat(key["start"]), datetime.fromisoformat(key["end"])
    if key["date"] != win["date"] or ready["date"] != win["date"] or not (start <= k_start < k_end <= end):
        return _unresolved("the keynote or readiness record is not on the event date inside the window",
                           ["B-keynote", "B-readiness", "B-event-window"], decision_records)

    def at(hhmm):
        h, m = map(int, hhmm.split(":"))
        return start.replace(hour=h, minute=m)

    blocks: list[dict] = []

    def add(kind, label, s, e, basis, evidence, decisions=()):
        blocks.append({"id": f"PRG-{len(blocks) + 1:02d}-{kind}", "kind": kind, "label": label,
                       "start": s.isoformat(), "end": e.isoformat(), "minutes": int((e - s).total_seconds() // 60),
                       "basis": basis, "evidence_ids": list(evidence), "decision_ids": list(decisions),
                       "owner": "Programme"})

    add("setup", "Setup and pre-opening readiness checks", at(ready["setup"]["start"]), at(ready["setup"]["end"]),
        SOURCE, ["B-readiness", "B-venue-hold"])

    roster = prog["roster"]
    first = math.ceil(len(roster) / 2)
    groups = {"demos-1": roster[:first], "demos-2": roster[first:]}
    minutes = {"opening": pd["PD-opening-minutes"]["value"], "lunch": pd["PD-lunch-minutes"]["value"],
               "break": pd["PD-break-minutes"]["value"], "closing": pd["PD-closing-minutes"]["value"]}
    order = pd["PD-order"]["value"]
    if order.count("break") != pd["PD-break-count"]["value"] or order[-1] != "closing" or "keynote" not in order:
        return _unresolved("PD-order is inconsistent with the break count or does not end with closing",
                           ["PD-order", "PD-break-count"], decision_records)
    t = start
    breaks = 0
    for step in order:
        if step == "keynote":
            if t > k_start:
                return _unresolved("items before the keynote do not fit before its fixed start",
                                   ["B-keynote", "PD-opening-minutes"], decision_records)
            if t < k_start:
                add("buffer", "Unallocated Programme buffer", t, k_start, UNALLOCATED, ["B-event-window"], ["PD-order"])
            add("keynote", "Keynote", k_start, k_end, SOURCE, ["B-keynote", "B-programme"])
            t = k_end
        elif step == "closing":
            c_start = end - timedelta(minutes=minutes["closing"])
            if t > c_start:
                return _unresolved("the programme does not fit inside the event window",
                                   ["B-event-window", "PD-order"], decision_records)
            if t < c_start:
                add("buffer", "Unallocated Programme buffer", t, c_start, UNALLOCATED, ["B-event-window"], ["PD-order"])
            add("closing", "Closing", c_start, end, PLANNER, ["B-event-window"], ["PD-closing-minutes", "PD-order"])
            t = end
        elif step in groups:
            for demo in groups[step]:
                s = t
                t = s + timedelta(minutes=prog["presentation_minutes"])
                add("demo", f"{demo} presentation", s, t, MIXED, ["B-programme"], ["PD-order", "PD-demo-grouping"])
                s = t
                t = s + timedelta(minutes=prog["changeover_minutes"])
                add("changeover", f"{demo} changeover", s, t, MIXED, ["B-programme"], ["PD-order", "PD-demo-grouping"])
        elif step == "break":
            breaks += 1
            s, t = t, t + timedelta(minutes=minutes["break"])
            add("break", f"Break {breaks}", s, t, PLANNER, ["N-BRIEF-planner_schedule_choices"],
                ["PD-break-minutes", "PD-break-count", "PD-order"])
        elif step in ("opening", "lunch"):
            s, t = t, t + timedelta(minutes=minutes[step])
            add(step, step.capitalize() if step == "lunch" else "Opening and welcome", s, t, PLANNER,
                ["B-event-window" if step == "opening" else "N-BRIEF-planner_schedule_choices"],
                [f"PD-{step}-minutes", "PD-order"])
        else:
            return _unresolved(f"unknown step '{step}' in PD-order", ["PD-order"], decision_records)

    add("teardown", "Teardown; all vendors clear", datetime.fromisoformat(tear["start"]),
        datetime.fromisoformat(tear["end"]), SOURCE, ["B-teardown", "B-readiness"])
    problems = check(blocks, start, end)
    if problems:
        return _unresolved("; ".join(problems), ["PD-order"], decision_records)
    unallocated = sum(b["minutes"] for b in blocks if b["kind"] == "buffer")
    return {"status": "planned", "reason": None, "date": win["date"], "blocks": blocks,
            "decisions": decision_records, "unallocated_minutes": unallocated,
            "evidence_ids": list(REQUIRED_BASELINE) + ["N-BRIEF-planner_schedule_choices"],
            "demo_count": len(roster), "missing_inputs": []}


def check(blocks: list[dict], window_start: datetime, window_end: datetime) -> list[str]:
    """No overlaps; programme items inside the event window; setup before it and teardown after it."""
    problems = []
    ordered = sorted(blocks, key=lambda b: b["start"])
    for a, b in zip(ordered, ordered[1:]):
        if datetime.fromisoformat(a["end"]) > datetime.fromisoformat(b["start"]):
            problems.append(f"{a['id']} overlaps {b['id']}")
    for b in blocks:
        s, e = datetime.fromisoformat(b["start"]), datetime.fromisoformat(b["end"])
        if e <= s:
            problems.append(f"{b['id']} has no duration")
        if b["kind"] == "setup" and e > window_start:
            problems.append(f"{b['id']} runs into the event window")
        elif b["kind"] == "teardown" and s < window_end:
            problems.append(f"{b['id']} starts before the event window closes")
        elif b["kind"] not in ("setup", "teardown") and (s < window_start or e > window_end):
            problems.append(f"{b['id']} is outside the event window")
    return problems


def _unresolved(reason, missing, decisions) -> dict:
    return {"status": "unresolved", "reason": reason, "date": None, "blocks": [], "decisions": decisions,
            "unallocated_minutes": None, "evidence_ids": [m for m in missing if not m.startswith("PD-")] or ["ASG-PROGRAMME"],
            "demo_count": None, "missing_inputs": missing}

"""Evidence citation helper shared by the Markdown renderers.

Renderers cite existing ids only. The appendix resolves each cited id to the record it names:
a claim's source, locator and retrieval time; a model record; a stakeholder line; a planner decision.
"""

from __future__ import annotations

from ..config import load_requirements_evidence


class Citations:
    def __init__(self, ri):
        self.ri = ri
        self.cited: list[str] = []
        self.claims = {c["id"]: c for c in ri.claims}
        self.records = {}
        d = ri.decision
        for group, label in (("baseline", "Phase 3 baseline"), ("checks", "Phase 3 check"),
                             ("options", "Phase 3 option"), ("approvals", "Phase 3 approval (pending)"),
                             ("dependencies", "Phase 3 dependency"), ("unresolved", "Phase 3 unresolved item"),
                             ("comparison", "Phase 3 comparison facts"), ("notes", "Phase 3 note")):
            for r in d[group]:
                self.records[r["id"]] = (label, r["summary"])
        rec = ri.recommendation
        for f in rec["factors"]:
            self.records[f["id"]] = ("Phase 4 factor comparison", f["summary"])
        self.records[rec["decision"]["id"]] = ("Phase 4 decision record", rec["decision"]["summary"])
        for c in rec["stakeholder_context"]:
            self.records[c["id"]] = ("Phase 4 stakeholder context", c["summary"])
        for d_ in ri.programme["decisions"]:
            self.records[d_["id"]] = ("Programme planner decision (pending Programme review)", d_["summary"])
        for b in ri.programme["blocks"]:
            self.records[b["id"]] = ("Programme block", f"{b['label']} {b['start'][11:16]}–{b['end'][11:16]}")
        for s in ri.sources:
            self.records[s["id"]] = ("Captured source", f"{s['summary']} ({s['retrieval_status']})")
        self.requirements = load_requirements_evidence()

    def __call__(self, *ids) -> str:
        ids = [i for i in dict.fromkeys(ids) if i]
        for i in ids:
            if i not in self.cited:
                self.cited.append(i)
        return f"_Evidence: {', '.join(ids)}_" if ids else ""

    def known(self, i: str) -> bool:
        return i in self.claims or i in self.records or i in self.requirements

    def describe(self, i: str) -> str:
        if i in self.claims:
            c = self.claims[i]
            prov = c.get("provenance") or []
            where = "; ".join(f"{p['source_id']} {p['locator']['value']} (retrieved {p['retrieved_at']})"
                              for p in prov[:2]) or "derived from other claims"
            return f"Claim ({c['kind']}, {c['support']}): {where}"
        if i in self.records:
            label, summary = self.records[i]
            return f"{label}: {summary[:160]}"
        if i in self.requirements:
            r = self.requirements[i]
            if r["group"] == "stakeholder":
                return f"Stakeholder interview {r['interview']} line {r['line']}: \"{r['quote'][:140]}\""
            return f"Assignment ({r['section']}): \"{r['quote'][:140]}\""
        return "UNRESOLVED REFERENCE"

    def appendix(self) -> str:
        rows = ["| ID | Resolves to |", "|---|---|"]
        rows += [f"| `{i}` | {self.describe(i).replace('|', '/')} |" for i in sorted(self.cited)]
        return "\n".join(rows)

"""Change impact derived from the existing evidence links (no separate dependency model).

For each captured source, follow evidence references forward (source -> claims -> baseline -> checks
-> options -> recommendation, approvals, programme) and report what would need reconsidering.
"""

from __future__ import annotations

from collections import defaultdict

SECTION_RULES = (  # (id prefix or marker, sections)
    (("B-headcount", "B-need-"), ("event-plan §3 headcount",)),
    (("B-event-window", "B-fallback-window", "B-keynote", "B-venue-hold", "B-teardown", "B-decision-deadline",
      "B-readiness", "B-programme", "B-time-requirements", "PRG-"), ("event-plan §4 timing and run of show",
                                                                       "event-calendar.ics")),
    (("B-budget-", "B-ceiling", "B-allowances"), ("event-plan §5 budget",)),
    (("B-accessibility", "N-FP-"), ("event-plan §7 accessibility",)),
    (("OPT-",), ("vendor-comparison.csv", "event-plan §6 options", "draft-communications.md")),
    (("TO-", "DEC-"), ("event-plan §8 recommendation",)),
    (("APR-",), ("event-plan §13 approvals", "draft-communications.md")),
)


def _nodes(ri) -> dict[str, list[str]]:
    d, rec, prog = ri.decision, ri.recommendation, ri.programme
    nodes: dict[str, list[str]] = {}
    for c in ri.claims:
        nodes[c["id"]] = list(c["evidence_ids"]) + list(c.get("source_ids", []))
    for group in ("baseline", "checks", "options", "approvals", "dependencies", "unresolved", "comparison", "notes"):
        for r in d[group]:
            nodes[r["id"]] = list(r["evidence_ids"])
    for f in rec["factors"]:
        nodes[f["id"]] = list(f["evidence_ids"])
    nodes[rec["decision"]["id"]] = list(rec["decision"]["evidence_ids"])
    for b in prog["blocks"]:
        nodes[b["id"]] = b["evidence_ids"] + b["decision_ids"]
    return nodes


def build(ri) -> dict:
    nodes = _nodes(ri)
    dependents = defaultdict(set)
    for n, evidence in nodes.items():
        for e in evidence:
            dependents[e].add(n)
    # observations belong to their source
    for s in ri.sources:
        for o in s.get("observations", []):
            dependents[s["id"]] |= dependents.get(o["id"], set())
    out = {}
    for s in ri.sources:
        seen, stack = set(), [s["id"]]
        while stack:
            for nxt in dependents.get(stack.pop(), ()):
                if nxt not in seen:
                    seen.add(nxt)
                    stack.append(nxt)
        sections = []
        for prefixes, secs in SECTION_RULES:
            if any(i.startswith(prefixes) or (p.startswith("CHK") and p in i) for i in seen for p in prefixes):
                sections += [x for x in secs if x not in sections]
        if any(i.startswith("CHK-") and "-budget-" in i for i in seen) and "event-plan §5 budget" not in sections:
            sections.append("event-plan §5 budget")
        if any(i.startswith("CHK-") and "-access-" in i for i in seen) and "event-plan §7 accessibility" not in sections:
            sections.append("event-plan §7 accessibility")
        out[s["id"]] = {"claims": sum(1 for i in seen if i.startswith(("N-", "X-", "P-"))),
                        "options": sorted(i for i in seen if i.startswith("OPT-")),
                        "sections": sections}
    return out

"""Validation of the rendered deliverables against the model they were rendered from."""

from __future__ import annotations

import csv
import io
import json
import re
from datetime import datetime

from . import calendar_ics, csv_out, plan_md
from ..programme import check as programme_check

CLAIM_WORDS = re.compile(r"\b(booked|confirmed|approved|selected|secured|reserved|committed)\b", re.I)
# A match is acceptable only when its sentence, before the word, negates or conditions it.
NEGATION = re.compile(r"\b(not|no|nothing|never|neither|nor|without|unless|until|pending|cannot|can't|isn't|"
                      r"aren't|hasn't|haven't|after|once|if|whether|before|un\w+)\b", re.I)
EMAIL = re.compile(r"[\w.+-]+@[\w-]+\.[A-Za-z]{2,}")
PHONE = re.compile(r"(\+\d{1,3}[\s-]?\d{2,4}[\s-]?\d{3,4}|\b\d{2,4}-\d{3,4}-\d{3,4}\b)")
TWD = re.compile(r"TWD ([\d,]+)")


def affirmative_claims(text: str) -> list[str]:
    """Sentences that state booking/confirmation/approval/selection affirmatively."""
    hits = []
    for m in CLAIM_WORDS.finditer(text):
        start = max(text.rfind(". ", 0, m.start()), text.rfind("\n", 0, m.start()), text.rfind("|", 0, m.start())) + 1
        if not NEGATION.search(text[start:m.start()]):
            hits.append(text[start:m.end() + 40].strip())
    return hits


def _ints(node, acc: set):
    if isinstance(node, bool):
        return acc
    if isinstance(node, int):
        acc.add(node)
    elif isinstance(node, dict):
        for v in node.values():
            _ints(v, acc)
    elif isinstance(node, list):
        for v in node:
            _ints(v, acc)
    return acc


def _unfold(ics: str) -> list[str]:
    lines = []
    for raw in ics.split("\r\n"):
        if raw.startswith(" ") and lines:
            lines[-1] += raw[1:]
        elif raw:
            lines.append(raw)
    return lines


def run(ri, view, files: dict[str, str], cited: dict[str, list[str]], citations_known) -> list[dict]:
    checks = []

    def add(cid, artifact, ok, summary, details=None):
        checks.append({"id": cid, "summary": summary, "evidence_ids": [ri.recommendation["decision"]["id"]],
                       "owner": None, "rationale": None if ok else f"failed: {details}", "outcome": "pass" if ok else "fail",
                       "artifact": artifact, "details": details})

    model_options = {o["id"]: o for o in ri.decision["options"]}
    rec = ri.recommendation
    allowed = _ints([ri.decision, ri.recommendation, ri.claims, ri.programme], set())

    # CSV
    rows = list(csv.reader(io.StringIO(files["vendor-comparison.csv"])))
    header, body = rows[0], rows[1:]
    add("V-csv-columns", "vendor-comparison.csv", header == csv_out.COLUMNS and header[:11] == csv_out.REQUIRED,
        "CSV has the 11 required columns in order, then the documented extra columns", header)
    problems = []
    if [r[0] for r in body] != [o["id"] for o in ri.decision["options"]]:
        problems.append("rows do not match the model's options in model order")
    for r in body:
        row = dict(zip(header, r))
        o = model_options.get(row["option_id"])
        if o is None:
            problems.append(f"unknown option {row['option_id']}")
            continue
        total = o["costs"]["total_with_allowances_twd"]
        if row["feasibility"] != o["feasibility"]:
            problems.append(f"{o['id']} feasibility differs")
        if row["cost_twd"] != ("" if total is None else str(total)):
            problems.append(f"{o['id']} cost differs")
        if row["recommendation_outcome"] != rec["status"]:
            problems.append(f"{o['id']} recommendation outcome differs")
        for col in ("quote_ids", "availability_status", "evidence_ids", "tradeoffs", "unresolved", "quote_details",
                    "allowances_twd"):
            try:
                json.loads(row[col])
            except ValueError:
                problems.append(f"{o['id']} {col} is not JSON")
        for col in ("planning_people", "cost_twd", "vendor_total_twd", "remaining_under_ceiling_twd"):
            if row[col] and not re.fullmatch(r"-?\d+", row[col]):
                problems.append(f"{o['id']} {col} is not an integer")
        if row["approval_status"] != "pending":
            problems.append(f"{o['id']} approval status is '{row['approval_status']}'")
        unknown = [i for i in json.loads(row["evidence_ids"]) if not citations_known(i)]
        if unknown:
            problems.append(f"{o['id']} unresolved evidence {unknown}")
    add("V-csv-rows", "vendor-comparison.csv", not problems,
        "Every CSV row matches its Phase 3 option (status, cost, approvals) and the Phase 4 outcome", problems)

    # Plan
    plan = files["event-plan.md"]
    positions = [plan.find(s) for s in plan_md.SECTIONS]
    add("V-plan-sections", "event-plan.md", -1 not in positions and positions == sorted(positions),
        "Event plan contains every required section in order", [s for s, p in zip(plan_md.SECTIONS, positions) if p < 0])
    banner_ok = (f"run status `{ri.run_status['status']}`" in plan and f"`{rec['status']}`" in plan)
    add("V-plan-banner", "event-plan.md", banner_ok, "Plan banner states the run status and recommendation outcome")
    rec_ok = (rec["recommendation"] is None and "Recommended for Operations review" not in plan
              and all("Recommended for Operations review" not in t for t in files.values())) or \
             (rec["recommendation"] is not None and rec["recommendation"] in plan)
    add("V-recommendation-match", "event-plan.md", rec_ok, "Deliverables state exactly the Phase 4 recommendation")

    # ICS
    lines = _unfold(files["event-calendar.ics"])
    expected = calendar_ics.events(view)
    vevents, cur = [], None
    for ln in lines:
        if ln == "BEGIN:VEVENT":
            cur = {}
        elif ln == "END:VEVENT":
            vevents.append(cur)
            cur = None
        elif cur is not None:
            k, _, v = ln.partition(":")
            cur[k] = v
    problems = []
    for need in ("BEGIN:VCALENDAR", "VERSION:2.0", "METHOD:PUBLISH", "END:VCALENDAR"):
        if need not in lines:
            problems.append(f"missing {need}")
    if any(ln.startswith(("ATTENDEE", "ORGANIZER")) for ln in lines):
        problems.append("ATTENDEE or ORGANIZER present")
    uids = [e.get("UID") for e in vevents]
    if len(uids) != len(set(uids)) or None in uids:
        problems.append("UIDs missing or not unique")
    for e, x in zip(vevents, expected):
        for key in ("DTSTAMP", "DTSTART;TZID=Asia/Taipei", "DTEND;TZID=Asia/Taipei"):
            if key not in e:
                problems.append(f"{e.get('UID')} missing {key}")
        if e.get("STATUS") != "TENTATIVE" or e.get("TRANSP") != "TRANSPARENT":
            problems.append(f"{e.get('UID')} not tentative/transparent")
        if e.get("DTSTART;TZID=Asia/Taipei") != calendar_ics._local(x["start"]) or \
                e.get("DTEND;TZID=Asia/Taipei") != calendar_ics._local(x["end"]):
            problems.append(f"{e.get('UID')} times differ from the model")
        for i in re.findall(r"Evidence: ([^.]+)\.", e.get("DESCRIPTION", "").replace("\\,", ",")):
            problems += [f"{e.get('UID')} unresolved evidence {j}" for j in i.split(", ") if not citations_known(j)]
    if len(vevents) != len(expected):
        problems.append(f"{len(vevents)} events, expected {len(expected)}")
    add("V-ics", "event-calendar.ics", not problems,
        "Calendar is a draft (PUBLISH), events tentative and transparent with stable UIDs, explicit timezone, "
        "no attendees, times equal to the model", problems)

    # Programme
    prog = ri.programme
    problems = []
    if prog["status"] == "planned":
        w = view["window"]
        problems += programme_check(prog["blocks"], datetime.fromisoformat(w["start"]), datetime.fromisoformat(w["end"]))
        pd_ids = {d["id"] for d in prog["decisions"]}
        base = {b["id"]: b for b in ri.decision["baseline"]}
        for b in prog["blocks"]:
            if b["basis"] not in ("source", "planner-decision", "source-duration, planner-placement", "unallocated"):
                problems.append(f"{b['id']} has unknown basis")
            if b["basis"] != "source" and not (set(b["decision_ids"]) and set(b["decision_ids"]) <= pd_ids):
                problems.append(f"{b['id']} lacks a recorded planner decision")
            for e in b["evidence_ids"]:
                if e.startswith("B-") and base.get(e, {}).get("support") != "supported":
                    problems.append(f"{b['id']} rests on unsupported {e}")
        demos = [b for b in prog["blocks"] if b["kind"] == "demo"]
        if len(demos) != prog["demo_count"]:
            problems.append("not every demo is scheduled exactly once")
    add("V-programme", "event-plan.md", not problems,
        "Run of show has no overlaps; every time is a source fact or a recorded Programme planner decision", problems)

    # Evidence, amounts, wording, privacy
    unknown = {name: [i for i in ids if not citations_known(i)] for name, ids in cited.items()}
    add("V-evidence", "event-plan.md", not any(unknown.values()), "Every cited evidence id resolves", unknown)
    bad_amounts = []
    for name, text in files.items():
        for m in TWD.finditer(text):
            if int(m.group(1).replace(",", "")) not in allowed:
                bad_amounts.append(f"{name}: TWD {m.group(1)}")
    for r in body:
        row = dict(zip(header, r))
        for col in ("cost_twd", "vendor_total_twd", "remaining_under_ceiling_twd"):
            if row[col] and int(row[col]) not in allowed:
                bad_amounts.append(f"csv {row['option_id']} {col}={row[col]}")
    add("V-amounts", "vendor-comparison.csv", not bad_amounts, "Every amount shown exists in the model", bad_amounts)
    claims = {name: affirmative_claims(text) for name, text in files.items()}
    add("V-wording", "draft-communications.md", not any(claims.values()),
        "No affirmative claim of booking, confirmation, approval, selection, reservation or commitment",
        {k: v for k, v in claims.items() if v})
    leaks = {name: EMAIL.findall(t) + PHONE.findall(t) for name, t in files.items()}
    add("V-privacy", "draft-communications.md", not any(leaks.values()), "No email addresses or phone numbers",
        {k: v for k, v in leaks.items() if v})
    comms = files["draft-communications.md"]
    sections = comms.count("\n## M")
    add("V-comms-drafts", "draft-communications.md", sections > 0 and comms.count("**UNSENT DRAFT**") == sections,
        "Every message is labelled UNSENT DRAFT", sections)
    return checks

